-- 2018-10-30T16:44:05.989
-- I forgot to set the DICTIONARY_ID_COMMENTS System Configurator
INSERT INTO AD_Element (AD_Client_ID,AD_Element_ID,AD_Org_ID,Created,CreatedBy,Description,Help,IsActive,Name,PrintName,Updated,UpdatedBy) VALUES (0,573921,0,TO_TIMESTAMP('2018-10-30 16:44:05','YYYY-MM-DD HH24:MI:SS'),100,'Sprachen verwalten','Das Fenster "Sprache" eröglicht Ihnen, mehrere Sprachen für die gleichzeitiige Verwendung durch den Nutzer zu definieren. Dies ermöglicht dem Nutzer, die gleichen Daten zu verwenden aber Fenster, Register und Felder in einer anderen Sprache anzuzeigen. Wenn eine Sprache "Systemsprache" ist können Sie (nach Übersetzung bzw. Einspielen eines Sprachpaketes) die Nutzeroberfläche in dieser Sprache darstellen lassen. Ansonsten wird die Sprache nur für den Druck von Dokumenten verwendet. Für die Kodierung der Sprache empfehlen wir das in Java übliche Format aus Sprache und Land (z.B. fr_CN - Kanadisches Französisch). Verifizierung der Überstzung erzeugt fehlende Übersetzungseinträge. Starten Sie diesen Prozess nach anlegen einer weiteren Sprache.','Y','Sprache','Sprache',TO_TIMESTAMP('2018-10-30 16:44:05','YYYY-MM-DD HH24:MI:SS'),100)
;

