INSERT INTO AD_Element (AD_Client_ID,AD_Element_ID,AD_Org_ID,Created,CreatedBy,Description,Help,IsActive,Name,PrintName,Updated,UpdatedBy) VALUES (0,573928,0,TO_TIMESTAMP('2018-10-30 16:44:06','YYYY-MM-DD HH24:MI:SS'),100,'Verwalten von Produkt-Preislisten','Das Fenster "Preisliste" ermöglicht, Produktpreislisten für Ihre Geschäftspartner anzulegen. Eine Preisliste bestimmt die Behandlung von Währung und Steuer. Preislistenversionen ermöglichen, gleichzeitig verschiedene Listen für verschiedene Zeiträume zu verwalten. Die aktuellste Liste - bezogen auf das Belegdatum - wird verwendet. <BR> Alle Preislisten haben drei Preise: Listenpreis, Standardpreis und Mindestpreis.<BR> Erster Schritt ist, eine Basispreisliste anzulegen. Sie können manuell Produkte hinzufügen und die Preise eingeben oder sie automatisch erzeugen. Die Basisipreisliste ist oft die Einkaufspreisliste mit dem Listenpreis  (''offizieller'' Verkaufspreis) und dem Standardpreis (Ihrem Einkaufspreis). Den Mindestpreiseintrag können Sie verwenden, um Ihren endgültigen Einkaufspreis nach Abschlägen, Rabatten usw. anzugeben.<BR> Preislisten können berechnet und kopiert werden. Um die Berechnung zu beschleunigen werden die Parameter gespeichert und bei der Erstellug einer neuen Preislistenversion verwendet.','Y','Preise','Preise',TO_TIMESTAMP('2018-10-30 16:44:06','YYYY-MM-DD HH24:MI:SS'),100)
;

