INSERT INTO AD_Element (AD_Client_ID,AD_Element_ID,AD_Org_ID,Created,CreatedBy,Description,Help,IsActive,Name,PrintName,Updated,UpdatedBy) VALUES (0,573933,0,TO_TIMESTAMP('2018-10-30 16:44:07','YYYY-MM-DD HH24:MI:SS'),100,'Verwalten von Druckformularen (Rechnungen, Schecks, ..)','Definieren Sie hier die Dokumente, die Sie in diesem Mandanten / dieser Organisation verwenden.  Beachten Sie, dass das Scheckformat im Fenster "Bank" zugeordnet wird.<p>
Die höchste Priorität hat das Format, dass Sie einem Dokumententyp zuordnen (z.B. ein spezifisches Formular für eine Rechnung für den Export).  Die nächste Ebene ist der Satz der Druckformate, den Sie für die druckende Organisation definiert haben. Der Standardsatz ist dann der Satz, der für alle Organisationen diese Mandanten definiert ist (Organisation=*).','Y','Druck - Formulare','Druck - Formulare',TO_TIMESTAMP('2018-10-30 16:44:07','YYYY-MM-DD HH24:MI:SS'),100)
;

